```
const sharp = require('sharp');
const path = require('path');
const fs = require('fs');
const async = require('async');
sharp.cache(false);


const filePath  = process.argv.pop();


function createArray(len){
  const array = [];

  for (let i = 0; i < len; i++){
    array.push(i);
  }

  return array;
}

const arr = createArray(10000);

const sourceBuffer = fs.readFileSync(filePath);

async function resize(source){
  const image = sharp(source).toBuffer();
  source = null;
  return image;
}

function logMemory(){
  const pr = process.memoryUsage();
  const logObject = {};
  for (let key in pr){
    logObject[key] =  parseInt((pr[key] / 1024 / 1024).toFixed(0));
  }

  console.log(logObject)

}

async.forEachLimit(arr, 1, async function (i){
  let resizedImage = await resize(sourceBuffer);

  resizedImage = null;
  logMemory();
}, function (err){

  console.log('done', err)
  setTimeout(logMemory, 3000)
})
```

